const parseString = require("xml2js").parseString;
const stripPrefix = require("xml2js").processors.stripPrefix;
const xmlContent = pm.response.text();

// Rows the airline does not open for seat selection. Override per environment with
// `excludedSeatRows` (e.g. "1,2,3,10"); set it to "" to disable.
const DEFAULT_EXCLUDED_SEAT_ROWS = '1,2,3';

// PADIS 9825 code 1 = "Restricted seat - General": the seat cannot be booked.
const RESTRICTED_SEAT_CHARACTERISTIC = '1';

// Accepts either a PTC (ADT / CHD / INF) or a literal PaxID (PAX1, PAX2, ...). PTC is the safer
// default: the adult is not always PAX1, and only DataLists/PaxList says which PaxID is the adult.
const DEFAULT_PAX_REF = 'ADT';

function asArray(val) {
    if (val == null) return [];
    return Array.isArray(val) ? val : [val];
}

function textValue(node) {
    if (node == null) return null;
    if (typeof node === 'string') return node;
    if (typeof node === 'object' && node._ != null) return node._;
    return String(node);
}

function excludedSeatRows() {
    const raw = pm.environment.get('excludedSeatRows');
    const value = raw == null ? DEFAULT_EXCLUDED_SEAT_ROWS : String(raw);
    return new Set(value.split(',').map(row => row.trim()).filter(Boolean));
}

// ALaCarteOffer is the only place that says which passenger an OfferItemID belongs to, and it is
// also the list the gateway validates the request against (OrderQuoteValidator.getNotMatchRequestIds).
// An id that is not in here comes back as IATA error 911 "ReshopOffer items do not match".
function indexOfferItems(aLaCarteOffer) {
    const byId = new Map();
    asArray(aLaCarteOffer.OfferItem).forEach(item => {
        if (!item.OfferItemID) return;
        byId.set(String(item.OfferItemID), {
            id: String(item.OfferItemID),
            paxRefIds: asArray(item?.Eligibility?.PaxRefID).map(String),
            price: textValue(item?.UnitPrice?.TotalAmount),
            currency: item?.UnitPrice?.TotalAmount?.$?.CurCode || null
        });
    });
    return byId;
}

// Every free seat carries one OfferItemRefID PER ELIGIBLE PASSENGER, in seat-map order — which is
// NOT the pax order of the request. Taking OfferItemRefID[0] therefore books whichever passenger
// happens to be listed first (PAX2 on this carrier) while the RQ still says PaxRefID PAX1.
// Expand each seat into one candidate per offer item so the pax can actually drive the pick.
function collectSeatCandidates(response, offerItemById) {
    const candidates = [];

    asArray(response.SeatMap).forEach((seatMap, mapIndex) => {
        asArray(seatMap.CabinCompartment).forEach((cabin, cabinIndex) => {
            const firstRow = Number(cabin.FirstRowNumber);
            const lastRow = Number(cabin.LastRowNumber);
            const hasCabinRange = !Number.isNaN(firstRow) && !Number.isNaN(lastRow);

            asArray(cabin.SeatRow).forEach(seatRow => {
                asArray(seatRow.Seat).forEach(seat => {
                    if (seat.OccupationStatusCode !== 'F') return;
                    if (!seat.ColumnID || !seat.RowNumber) return;

                    const characteristics = asArray(seat.SeatCharacteristicCode).map(textValue);
                    if (characteristics.includes(RESTRICTED_SEAT_CHARACTERISTIC)) return;

                    const row = Number(seat.RowNumber);

                    asArray(seat.OfferItemRefID).map(textValue).filter(Boolean).forEach(offerItemRefId => {
                        const offerItem = offerItemById.get(offerItemRefId);
                        // Drop refs the ALaCarteOffer does not carry — the gateway would reject them.
                        if (!offerItem) return;

                        candidates.push({
                            mapIndex,
                            cabinIndex,
                            row: String(seat.RowNumber),
                            column: String(seat.ColumnID),
                            label: String(seat.RowNumber) + seat.ColumnID,
                            offerItemRefId,
                            paxRefIds: offerItem.paxRefIds,
                            price: offerItem.price,
                            currency: offerItem.currency,
                            // The same physical seat repeats in every CabinCompartment with different
                            // OfferItemRefIDs. Only the compartment whose declared row range covers the
                            // row carries the ids that belong to that seat.
                            inCabinRange: hasCabinRange ? row >= firstRow && row <= lastRow : true
                        });
                    });
                });
            });
        });
    });

    return candidates;
}

// `seat_pax_ref` may be a PTC or a PaxID. Resolve it to the set of PaxIDs it covers so the pick
// follows the passenger type rather than the order the seat map happens to list items in.
function resolvePaxIds(response, targetPax) {
    const wanted = String(targetPax).trim().toUpperCase();
    const paxList = asArray(response?.DataLists?.PaxList?.Pax);

    const byPaxId = paxList.filter(pax => String(pax.PaxID).trim().toUpperCase() === wanted);
    if (byPaxId.length) {
        return { paxIds: new Set(byPaxId.map(pax => String(pax.PaxID))), matchedBy: 'PaxID' };
    }

    const byPtc = paxList.filter(pax => String(pax.PTC).trim().toUpperCase() === wanted);
    if (byPtc.length) {
        return { paxIds: new Set(byPtc.map(pax => String(pax.PaxID))), matchedBy: 'PTC' };
    }

    // No PaxList (or an unknown token): fall back to matching the ref literally.
    return { paxIds: new Set([wanted]), matchedBy: 'literal' };
}

function matchesPax(candidate, paxIds) {
    return candidate.paxRefIds.some(pax => paxIds.has(String(pax).trim()));
}

// The same physical seat is repeated in every CabinCompartment with a different OfferItemRefID.
// reshop-service binds the seat to the copy from the FIRST compartment block: picking the
// row-range copy instead yields "Selected seat 7/A doesn't belong to offer item ..." on
// reserve-seats, even though OrderQuote accepts it (OrderQuote only checks the id exists).
// Set seatCabinBlock=range to prefer the compartment whose declared row range covers the row.
function pickPreferred(candidates) {
    if (!candidates.length) return null;
    if (String(pm.environment.get("seatCabinBlock") || "first").toLowerCase() === "range") {
        return candidates.find(c => c.inCabinRange) || candidates[0];
    }
    return candidates.slice().sort((a, b) => a.cabinIndex - b.cabinIndex)[0];
}

