function collectBookableSeats(response) {
    const seats = [];

    toArray(response.SeatMap).forEach((seatMap, mapIndex) => {
        toArray(seatMap.CabinCompartment).forEach((cabin, compartmentIndex) => {
            toArray(cabin.SeatRow).forEach(seatRow => {
                toArray(seatRow.Seat).forEach(seat => {
                    const offerItemRefIds = toArray(seat.OfferItemRefID).map(textValue).filter(Boolean);
                    const characteristics = toArray(seat.SeatCharacteristicCode).map(textValue);

                    if (
                        seat.OccupationStatusCode === 'F' &&
                        seat.ColumnID &&
                        seat.RowNumber &&
                        offerItemRefIds.length &&
                        !characteristics.includes(RESTRICTED_SEAT_CHARACTERISTIC)
                    ) {
                        seats.push({
                            mapIndex,
                            compartmentIndex,
                            row: String(seat.RowNumber),
                            column: String(seat.ColumnID),
                            // One OfferItemRefID per requested passenger, in response order.
                            offerItemRefIds,
                            label: String(seat.RowNumber) + seat.ColumnID
                        });
                    }
                });
            });
        });
    });

    return seats;
}

