            console.warn('No Eligibility/PaxRefID in ALaCarteOffer - falling back to positional OfferItemRefID matching');
        }

        function offerItemFor(seat, paxRefId, paxIndex) {
            if (!hasEligibility) return seat.offerItemRefIds[paxIndex] || null;
            return seat.offerItemRefIds.find(ref => paxRefsOf(ref).indexOf(paxRefId) !== -1) || null;
        }

        // --- collect the seats we are allowed to pick from ---
        const bookableSeats = collectBookableSeats(response);
        const skipRows = excludedSeatRows();
        const selectableSeats = bookableSeats.filter(seat => !skipRows.has(seat.row));

        pm.test('at least one bookable seat', function () {
            pm.expect(bookableSeats.length, 'No free seats (OccupationStatusCode=F)').to.be.above(0);
        });

        pm.test('at least one seat outside the excluded rows', function () {
            pm.expect(selectableSeats.length,
                `All free seats are in excluded rows [${[...skipRows].join(',')}]`).to.be.above(0);
        });

        const targetPaxRefIds = csvValues('targetPaxRefIds', DEFAULT_TARGET_PAX_REF_IDS);
        const targetRow = pm.environment.get('targetSeatRow');
        const targetCol = pm.environment.get('targetSeatColumn');
        const targetSegmentIndex = Number(pm.environment.get('targetSegmentIndex') || 0);

        pm.test('at least as many selectable seats as passengers', function () {
            pm.expect(selectableSeats.length,
                `Need ${targetPaxRefIds.length} seats, only ${selectableSeats.length} selectable`)
                .to.be.at.least(targetPaxRefIds.length);
        });

        // --- one distinct seat per passenger ---
        const taken = new Set();
        const selections = [];

        targetPaxRefIds.forEach((paxRefId, paxIndex) => {
            let selectedSeat = null;

            // An explicit target pins the FIRST passenger's seat and wins over excludedSeatRows,
            // so a closed row can still be tested on purpose. The rest are picked automatically.
            if (paxIndex === 0 && targetRow && targetCol) {
                selectedSeat = pickBookable(bookableSeats.filter(seat =>
                    seat.mapIndex === targetSegmentIndex &&
                    seat.row === String(targetRow) &&
                    seat.column.toUpperCase() === String(targetCol).toUpperCase()
                ));

                if (selectedSeat && skipRows.has(selectedSeat.row)) {
                    console.warn(`targetSeatRow ${targetRow} is in excludedSeatRows — the airline may not open this row for booking`);
                }

                pm.test(`seat ${targetRow}${targetCol} is bookable`, function () {
                    pm.expect(selectedSeat, `Seat ${targetRow}${targetCol} not free on segment ${targetSegmentIndex}`).to.exist;
                });
            }

            if (!selectedSeat) {
                const candidates = selectableSeats.filter(seat =>
                    !taken.has(seatKey(seat)) && offerItemFor(seat, paxRefId, paxIndex));
                selectedSeat = pickBookable(candidates.filter(seat => seat.mapIndex === targetSegmentIndex))
                    || pickBookable(candidates);
            }

            const offerItemId = selectedSeat ? offerItemFor(selectedSeat, paxRefId, paxIndex) : null;

            pm.test(`seat selected for ${paxRefId}`, function () {
                pm.expect(selectedSeat, `No free seat left for ${paxRefId}`).to.exist;
                pm.expect(offerItemId, `No seat offer item eligible for ${paxRefId}`).to.exist;
            });

            if (!selectedSeat || !offerItemId) return;

            taken.add(seatKey(selectedSeat));
            selections.push({ paxRefId, seat: selectedSeat, offerItemId });
        });

        if (selections.length !== targetPaxRefIds.length) {
            throw new Error(`Seated ${selections.length}/${targetPaxRefIds.length} passengers — check excludedSeatRows / targetSeatRow / targetSeatColumn`);
        }

        // --- export one set of variables per passenger, plus the first passenger unsuffixed ---
        // The unsuffixed names are what the single-seat requests in the other folders still read.
        let seatTotal = 0;
        selections.forEach((selection, index) => {
            const suffix = '_' + selection.paxRefId;
            const totalAmount = (offerItemById[selection.offerItemId] || {}).UnitPrice;
            const amount = totalAmount && totalAmount.TotalAmount;

            const values = {
                seatOfferItemId: selection.offerItemId,
                seatRow: selection.seat.row,
                seatColumn: selection.seat.column,
                seatLabel: selection.seat.label
            };
            if (amount) {
                values.seatPrice = textValue(amount);
                if (amount.$ && amount.$.CurCode) values.seatCurrency = amount.$.CurCode;
                seatTotal += Number(textValue(amount)) || 0;
            }

            Object.keys(values).forEach(key => {
                pm.environment.set(key + suffix, values[key]);
                if (index === 0) pm.environment.set(key, values[key]);
            });
            if (index === 0) pm.environment.set('seatPaxRefId', selection.paxRefId);
        });

        pm.environment.set('seatPaxRefIds', selections.map(s => s.paxRefId).join(','));
        pm.environment.set('seatTotalPrice', String(seatTotal));

        console.log('seatOfferId    =', seatOfferId);
        console.log('seatTotalPrice =', seatTotal, pm.environment.get('seatCurrency'));
        selections.forEach(selection => console.log(
            `  ${selection.paxRefId} -> seat ${selection.seat.label}`,
            `(seg ${selection.seat.mapIndex}, compartment ${selection.seat.compartmentIndex})`,
            `@ ${pm.environment.get('seatPrice_' + selection.paxRefId)}`,
            `item ${selection.offerItemId}`));
        console.log('excludedSeatRows =', [...skipRows].join(',') || '(none)');
        console.log('free seats       =', bookableSeats.length, '→ selectable', selectableSeats.length);

    } catch (e) {
        console.error('Could not parse SeatAvailabilityRS:', e.message);
        clearSeatVars();
        console.log('Full parsed object:', JSON.stringify(result, null, 2));
    }
});

const xml2js = require('xml2js');
const xmlContent = pm.response.text();

// Require the necessary xml2js components
const parseString = require('xml2js').parseString;
const stripPrefix = require('xml2js').processors.stripPrefix;

parseString(xmlContent, {
    // Optional configuration for cleaner access
    tagNameProcessors: [stripPrefix],
    explicitArray: false,
    ignoreAttrs: true
}, function (err, result) {
    if (err) {
        console.error('Error parsing XML:', err);
        return;
    }

    // Now 'result' is your fully parsed JavaScript object.
    // We wrap this in a try-catch block in case the path is missing in some responses.
    try {
        // Navigate to Offer list
        let offers = result.IATA_AirShoppingRS.Response.OffersGroup.CarrierOffers.Offer;

        // Always array
        if (!Array.isArray(offers)) {
            offers = [offers];
        }

        let offerIds = [];
        let offerItemsByOffer = []; // nested list

        offers.forEach(offer => {

            // Store ID
            offerIds.push(offer.OfferID);

            // Extract OfferItem list
            let items = offer.OfferItem;
            if (!Array.isArray(items)) {
                items = [items];
            }

            // Extract OfferItemID for this offer
            let itemIds = items.map(i => i.OfferItemID);

            offerItemsByOffer.push(itemIds);
        });

        // Save to environment
        pm.environment.set("offerIds", JSON.stringify(offerIds));
        pm.environment.set("offerItemsByOffer", JSON.stringify(offerItemsByOffer));


        offerIds.forEach((id, index) => {
            pm.environment.set(`offerId${index}`, id);
        });

        for (let i = 0; i < offerItemsByOffer.length; i++) {
            for (let j = 0; j < offerItemsByOffer[i].length; j++) {
                pm.environment.set(`offerItemId${i}_${j}`, offerItemsByOffer[i][j]);
                console.log(offerItemsByOffer[i][j]);
            }
        }

        console.log("Offer IDs:", offerIds);
        console.log("Offer Items By Offer:", offerItemsByOffer);

    } catch (e) {
        console.error('Could not find the expected path in the XML structure:', e.message);
        console.log('Full parsed object structure:', result); // Log the whole object to debug the path
    }
});

function formatWithTimezone(date, tzOffsetMinutes) {
    const pad = (n, width = 2) => String(n).padStart(width, '0');

    const sign = tzOffsetMinutes >= 0 ? "+" : "-";
    const abs = Math.abs(tzOffsetMinutes);
    const offsetHours = pad(Math.floor(abs / 60));
    const offsetMinutes = pad(abs % 60);

    return (
        date.getFullYear() +
        "-" + pad(date.getMonth() + 1) +
        "-" + pad(date.getDate()) +
        "T" + pad(date.getHours()) +
        ":" + pad(date.getMinutes()) +
        ":" + pad(date.getSeconds()) +
        "." + pad(date.getMilliseconds(), 3) +
        sign + offsetHours + ":" + offsetMinutes
    );
}

